param([string]$OutFile="",[switch]$IncludeLogs)
$ErrorActionPreference='Stop';$Root=Split-Path -Parent $PSScriptRoot;$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';if(-not$OutFile){$OutFile=Join-Path $Root "Metatron-Support-$stamp.zip"};$tmp=Join-Path ([IO.Path]::GetTempPath()) "metatron-support-$stamp";New-Item -ItemType Directory -Force $tmp|Out-Null;try{@{generated_at=(Get-Date).ToUniversalTime().ToString('o');os=(Get-CimInstance Win32_OperatingSystem|select Caption,Version,BuildNumber,OSArchitecture);computer=(Get-CimInstance Win32_ComputerSystem|select Manufacturer,Model,TotalPhysicalMemory);cpu=(Get-CimInstance Win32_Processor|select Name,NumberOfCores,NumberOfLogicalProcessors);display=(Get-CimInstance Win32_VideoController|select Name,DriverVersion,AdapterRAM);npu=(Get-PnpDevice -PresentOnly -ErrorAction SilentlyContinue|?{$_.FriendlyName-match'NPU|Neural|AI Boost|Hexagon|Ryzen AI'}|select FriendlyName,Class,Status,InstanceId)}|ConvertTo-Json -Depth 6|Set-Content -Encoding UTF8 (Join-Path $tmp 'system.json');& python $PSScriptRoot\product_audit.py --json-out (Join-Path $tmp 'product-audit.json')|Out-Null;& python $PSScriptRoot\Verify-Accelerators.py --report (Join-Path $tmp 'accelerators.json')|Out-Null;if($env:METATRON_SPEECH_CMD){& python $PSScriptRoot\Verify-SpeechRuntime.py --json-out (Join-Path $tmp 'speech.json')|Out-Null};@{note='Excludes secrets, SQLite database, transcript history and audio.'}|ConvertTo-Json|Set-Content -Encoding UTF8 (Join-Path $tmp 'privacy-note.json');Compress-Archive -Path (Join-Path $tmp '*') -DestinationPath $OutFile -Force}finally{Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue};Write-Host "Support bundle: $OutFile"
